55: static pty_baton* get_pty_baton(int id) {
56:   auto it = std::find_if(ptyHandles.begin(), ptyHandles.end(), [id](const auto& ptyHandle) {
57:     return ptyHandle->id == id;
58:   });
59:   if (it != ptyHandles.end()) {
60:     return it->get();
61:   }
62:   return nullptr;
63: }
