65: static bool remove_pty_baton(int id) {
66:   auto it = std::remove_if(ptyHandles.begin(), ptyHandles.end(), [id](const auto& ptyHandle) {
67:     return ptyHandle->id == id;
68:   });
69:   if (it != ptyHandles.end()) {
70:     ptyHandles.erase(it);
71:     return true;
72:   }
73:   return false;
