80: void SetupExitCallback(Napi::Env env, Napi::Function cb, pty_baton* baton) {
81:   std::thread *th = new std::thread;
82:   // Don't use Napi::AsyncWorker which is limited by UV_THREADPOOL_SIZE.
83:   auto tsfn = Napi::ThreadSafeFunction::New(
84:       env,
85:       cb,                           // JavaScript function called asynchronously
86:       "SetupExitCallback_resource", // Name
87:       0,                            // Unlimited queue
88:       1,                            // Only one thread will use this initially
89:       [th](Napi::Env) {   // Finalizer used to clean threads up
90:         th->join();
91:         delete th;
92:       });
93:   *th = std::thread([tsfn = std::move(tsfn), baton] {
94:     auto callback = [](Napi::Env env, Napi::Function cb, ExitEvent *exit_event) {
95:       cb.Call({Napi::Number::New(env, exit_event->exit_code)});
96:       delete exit_event;
97:     };
98: 
99:     ExitEvent *exit_event = new ExitEvent;
100:     // Wait for process to complete.
101:     WaitForSingleObject(baton->hShell, INFINITE);
102:     // Get process exit code.
103:     GetExitCodeProcess(baton->hShell, (LPDWORD)(&exit_event->exit_code));
104:     // Clean up handles
105:     CloseHandle(baton->hShell);
106:     assert(remove_pty_baton(baton->id));
107: 
108:     auto status = tsfn.BlockingCall(exit_event, callback); // In main thread
109:     switch (status) {
110:       case napi_closing:
111:         break;
112: 
113:       case napi_queue_full:
114:         Napi::Error::Fatal("SetupExitCallback", "Queue was full");
115: 
116:       case napi_ok:
117:         if (tsfn.Release() != napi_ok) {
118:           Napi::Error::Fatal("SetupExitCallback", "ThreadSafeFunction.Release() failed");
119:         }
120:         break;
121: 
122:       default:
123:         Napi::Error::Fatal("SetupExitCallback", "ThreadSafeFunction.BlockingCall() failed");
124:     }
125:   });
126: }
