136: bool createDataServerPipe(bool write,
137:                           std::wstring kind,
138:                           HANDLE* hServer,
139:                           std::wstring &name,
140:                           const std::wstring &pipeName)
141: {
142:   *hServer = INVALID_HANDLE_VALUE;
143: 
144:   name = L"\\\\.\\pipe\\" + pipeName + L"-" + kind;
145: 
146:   const DWORD winOpenMode =  PIPE_ACCESS_INBOUND | PIPE_ACCESS_OUTBOUND | FILE_FLAG_FIRST_PIPE_INSTANCE/*  | FILE_FLAG_OVERLAPPED */;
147: 
148:   SECURITY_ATTRIBUTES sa = {};
149:   sa.nLength = sizeof(sa);
150: 
151:   *hServer = CreateNamedPipeW(
152:       name.c_str(),
153:       /*dwOpenMode=*/winOpenMode,
154:       /*dwPipeMode=*/PIPE_TYPE_BYTE | PIPE_READMODE_BYTE | PIPE_WAIT,
155:       /*nMaxInstances=*/1,
156:       /*nOutBufferSize=*/128 * 1024,
157:       /*nInBufferSize=*/128 * 1024,
158:       /*nDefaultTimeOut=*/30000,
159:       &sa);
160: 
161:   return *hServer != INVALID_HANDLE_VALUE;
162: }
