164: HANDLE LoadConptyDll(const Napi::CallbackInfo& info,
165:                      const bool useConptyDll)
166: {
167:   if (!useConptyDll) {
168:     return LoadLibraryExW(L"kernel32.dll", 0, 0);
169:   }
170:   wchar_t currentDir[MAX_PATH];
171:   HMODULE hModule = GetModuleHandleA("conpty.node");
172:   if (hModule == NULL) {
173:     throw errorWithCode(info, "Failed to get conpty.node module handle");
174:   }
175:   DWORD result = GetModuleFileNameW(hModule, currentDir, MAX_PATH);
176:   if (result == 0) {
177:     throw errorWithCode(info, "Failed to get conpty.node module file name");
178:   }
179:   PathRemoveFileSpecW(currentDir);
180:   wchar_t conptyDllPath[MAX_PATH];
181:   PathCombineW(conptyDllPath, currentDir, L"conpty\\conpty.dll");
182:   if (!path_util::file_exists(conptyDllPath)) {
183:     std::wstring errorMessage = L"Cannot find conpty.dll at " + std::wstring(conptyDllPath);
184:     std::string errorMessageStr = path_util::wstring_to_string(errorMessage);
185:     throw errorWithCode(info, errorMessageStr.c_str());
186:   }
187: 
188:   return LoadLibraryW(conptyDllPath);
189: }
