191: HRESULT CreateNamedPipesAndPseudoConsole(const Napi::CallbackInfo& info,
192:                                          COORD size,
193:                                          DWORD dwFlags,
194:                                          HANDLE *phInput,
195:                                          HANDLE *phOutput,
196:                                          HPCON* phPC,
197:                                          std::wstring& inName,
198:                                          std::wstring& outName,
199:                                          const std::wstring& pipeName,
200:                                          const bool useConptyDll)
201: {
202:   HANDLE hLibrary = LoadConptyDll(info, useConptyDll);
203:   DWORD error = GetLastError();
204:   bool fLoadedDll = hLibrary != nullptr;
205:   if (fLoadedDll)
206:   {
207:     PFNCREATEPSEUDOCONSOLE const pfnCreate = (PFNCREATEPSEUDOCONSOLE)GetProcAddress(
208:         (HMODULE)hLibrary,
209:         useConptyDll ? "ConptyCreatePseudoConsole" : "CreatePseudoConsole");
210:     if (pfnCreate)
211:     {
212:       if (phPC == NULL || phInput == NULL || phOutput == NULL)
213:       {
214:         return E_INVALIDARG;
215:       }
216: 
217:       bool success = createDataServerPipe(true, L"in", phInput, inName, pipeName);
218:       if (!success)
219:       {
220:         return HRESULT_FROM_WIN32(GetLastError());
221:       }
222:       success = createDataServerPipe(false, L"out", phOutput, outName, pipeName);
223:       if (!success)
224:       {
225:         return HRESULT_FROM_WIN32(GetLastError());
226:       }
227:       return pfnCreate(size, *phInput, *phOutput, dwFlags, phPC);
228:     }
229:     else
230:     {
231:       // Failed to find CreatePseudoConsole in kernel32. This is likely because
232:       //    the user is not running a build of Windows that supports that API.
233:       //    We should fall back to winpty in this case.
234:       return HRESULT_FROM_WIN32(GetLastError());
235:     }
236:   } else {
237:     throw errorWithCode(info, "Failed to load conpty.dll");
238:   }
239: 
240:   // Failed to find  kernel32. This is realy unlikely - honestly no idea how
241:   //    this is even possible to hit. But if it does happen, fall back to winpty.
242:   return HRESULT_FROM_WIN32(GetLastError());
243: }
