245: static Napi::Value PtyStartProcess(const Napi::CallbackInfo& info) {
246:   Napi::Env env(info.Env());
247:   Napi::HandleScope scope(env);
248: 
249:   Napi::Object marshal;
250:   std::wstring inName, outName;
251:   BOOL fSuccess = FALSE;
252:   std::unique_ptr<wchar_t[]> mutableCommandline;
253:   PROCESS_INFORMATION _piClient{};
254: 
255:   if (info.Length() != 7 ||
256:       !info[0].IsString() ||
257:       !info[1].IsNumber() ||
258:       !info[2].IsNumber() ||
259:       !info[3].IsBoolean() ||
260:       !info[4].IsString() ||
261:       !info[5].IsBoolean() ||
262:       !info[6].IsBoolean()) {
263:     throw Napi::Error::New(env, "Usage: pty.startProcess(file, cols, rows, debug, pipeName, inheritCursor, useConptyDll)");
264:   }
265: 
266:   const std::wstring filename(path_util::to_wstring(info[0].As<Napi::String>()));
267:   const SHORT cols = static_cast<SHORT>(info[1].As<Napi::Number>().Uint32Value());
268:   const SHORT rows = static_cast<SHORT>(info[2].As<Napi::Number>().Uint32Value());
269:   const bool debug = info[3].As<Napi::Boolean>().Value();
270:   const std::wstring pipeName(path_util::to_wstring(info[4].As<Napi::String>()));
271:   const bool inheritCursor = info[5].As<Napi::Boolean>().Value();
272:   const bool useConptyDll = info[6].As<Napi::Boolean>().Value();
273: 
274:   // use environment 'Path' variable to determine location of
275:   // the relative path that we have recieved (e.g cmd.exe)
276:   std::wstring shellpath;
277:   if (::PathIsRelativeW(filename.c_str())) {
278:     shellpath = path_util::get_shell_path(filename.c_str());
279:   } else {
280:     shellpath = filename;
281:   }
282: 
283:   if (shellpath.empty() || !path_util::file_exists(shellpath)) {
284:     std::string why;
285:     why += "File not found: ";
286:     why += path_util::wstring_to_string(shellpath);
287:     throw Napi::Error::New(env, why);
288:   }
289: 
290:   HANDLE hIn, hOut;
291:   HPCON hpc;
292:   HRESULT hr = CreateNamedPipesAndPseudoConsole(info, {cols, rows}, inheritCursor ? 1/*PSEUDOCONSOLE_INHERIT_CURSOR*/ : 0, &hIn, &hOut, &hpc, inName, outName, pipeName, useConptyDll);
293: 
294:   // Restore default handling of ctrl+c
295:   SetConsoleCtrlHandler(NULL, FALSE);
296: 
297:   // Set return values
298:   marshal = Napi::Object::New(env);
299: 
300:   if (SUCCEEDED(hr)) {
301:     // We were able to instantiate a conpty
302:     const int ptyId = InterlockedIncrement(&ptyCounter);
303:     marshal.Set("pty", Napi::Number::New(env, ptyId));
304:     ptyHandles.emplace_back(
305:         std::make_unique<pty_baton>(ptyId, hIn, hOut, hpc));
306:   } else {
307:     throw Napi::Error::New(env, "Cannot launch conpty");
308:   }
309: 
310:   std::string inNameStr = path_util::wstring_to_string(inName);
311:   if (inNameStr.empty()) {
312:     throw Napi::Error::New(env, "Failed to initialize conpty conin");
313:   }
314:   std::string outNameStr = path_util::wstring_to_string(outName);
315:   if (outNameStr.empty()) {
316:     throw Napi::Error::New(env, "Failed to initialize conpty conout");
317:   }
318: 
319:   marshal.Set("fd", Napi::Number::New(env, -1));
320:   marshal.Set("conin", Napi::String::New(env, inNameStr));
321:   marshal.Set("conout", Napi::String::New(env, outNameStr));
322:   return marshal;
323: }
