325: static Napi::Value PtyConnect(const Napi::CallbackInfo& info) {
326:   Napi::Env env(info.Env());
327:   Napi::HandleScope scope(env);
328: 
329:   // If we're working with conpty's we need to call ConnectNamedPipe here AFTER
