334:   BOOL fSuccess = FALSE;
335: 
336:   if (info.Length() != 6 ||
337:       !info[0].IsNumber() ||
338:       !info[1].IsString() ||
339:       !info[2].IsString() ||
340:       !info[3].IsArray() ||
